"""Multi-dimensional proposal evaluation.

Scores proposals on 5 dimensions: Novelty, Feasibility, Completeness,
Rigor, Clarity. Each dimension gets a 0-1 score with written justification.
"""
from __future__ import annotations

import logging
import re
from dataclasses import dataclass, field
from pathlib import Path
from typing import Any

logger = logging.getLogger(__name__)

_PROMPT_PATH = Path(__file__).parent / "prompts" / "evaluation.md"

DIMENSIONS = ["novelty", "feasibility", "completeness", "rigor", "clarity"]


@dataclass
class DimensionScore:
    """Score and justification for a single evaluation dimension."""
    score: float = 0.0
    justification: str = ""

    def __post_init__(self):
        self.score = max(0.0, min(1.0, self.score))


@dataclass
class ProposalEvaluation:
    """Full 5-dimension evaluation of a research proposal."""
    novelty: DimensionScore = field(default_factory=DimensionScore)
    feasibility: DimensionScore = field(default_factory=DimensionScore)
    completeness: DimensionScore = field(default_factory=DimensionScore)
    rigor: DimensionScore = field(default_factory=DimensionScore)
    clarity: DimensionScore = field(default_factory=DimensionScore)
    overall: float = 0.0

    def to_dict(self) -> dict:
        return {
            "novelty": {"score": self.novelty.score, "justification": self.novelty.justification},
            "feasibility": {"score": self.feasibility.score, "justification": self.feasibility.justification},
            "completeness": {"score": self.completeness.score, "justification": self.completeness.justification},
            "rigor": {"score": self.rigor.score, "justification": self.rigor.justification},
            "clarity": {"score": self.clarity.score, "justification": self.clarity.justification},
            "overall": self.overall,
        }

    @classmethod
    def from_dict(cls, data: dict) -> ProposalEvaluation:
        def _ds(d):
            if isinstance(d, dict):
                return DimensionScore(score=d.get("score", 0.0), justification=d.get("justification", ""))
            return DimensionScore()
        return cls(
            novelty=_ds(data.get("novelty", {})),
            feasibility=_ds(data.get("feasibility", {})),
            completeness=_ds(data.get("completeness", {})),
            rigor=_ds(data.get("rigor", {})),
            clarity=_ds(data.get("clarity", {})),
            overall=data.get("overall", 0.0),
        )


class ProposalEvaluator:
    """Evaluates research proposals on 5 dimensions using LLM."""

    def __init__(self, provider: Any = None) -> None:
        self._provider = provider
        self._system_prompt = self._load_prompt()

    @staticmethod
    def _load_prompt() -> str:
        if _PROMPT_PATH.exists():
            return _PROMPT_PATH.read_text(encoding="utf-8")
        return "Evaluate the proposal on 5 dimensions: Novelty, Feasibility, Completeness, Rigor, Clarity."

    async def evaluate(self, proposal_text: str) -> ProposalEvaluation:
        """Evaluate a proposal on 5 dimensions.

        Returns:
            ProposalEvaluation with scores and justifications.
            Returns default evaluation if provider is unavailable.
        """
        if self._provider is None or not proposal_text:
            return ProposalEvaluation()

        user_prompt = f"Evaluate the following research proposal:\n\n{proposal_text[:8000]}"

        try:
            response = await self._provider.complete(
                system_prompt=self._system_prompt,
                user_prompt=user_prompt,
                max_tokens=1000,
            )
        except TimeoutError:
            logger.warning("LLM timeout during proposal evaluation — returning default scores")
            return ProposalEvaluation()
        except Exception as e:
            logger.warning("LLM error during proposal evaluation: %s — returning default", e)
            return ProposalEvaluation()

        return self._parse_response(response)

    @staticmethod
    def _parse_response(text: str) -> ProposalEvaluation:
        """Parse structured 5-dimension evaluation from LLM response."""
        scores = {}
        justifications = {}

        for dim in DIMENSIONS:
            score_match = re.search(
                rf"{dim}_SCORE:\s*([\d.]+)", text, re.IGNORECASE
            )
            if score_match:
                try:
                    scores[dim] = float(score_match.group(1))
                except ValueError:
                    scores[dim] = 0.0

            just_match = re.search(
                rf"{dim}_JUSTIFICATION:\s*(.+?)(?=\w+_SCORE:|\w+_JUSTIFICATION:|OVERALL_SCORE:|$)",
                text, re.IGNORECASE | re.DOTALL,
            )
            if just_match:
                justifications[dim] = just_match.group(1).strip()

        overall = 0.0
        overall_match = re.search(r"OVERALL_SCORE:\s*([\d.]+)", text, re.IGNORECASE)
        if overall_match:
            try:
                overall = float(overall_match.group(1))
            except ValueError:
                overall = 0.0

        if not overall and scores:
            overall = sum(scores.values()) / len(scores) if scores else 0.0

        return ProposalEvaluation(
            novelty=DimensionScore(score=scores.get("novelty", 0.0), justification=justifications.get("novelty", "")),
            feasibility=DimensionScore(score=scores.get("feasibility", 0.0), justification=justifications.get("feasibility", "")),
            completeness=DimensionScore(score=scores.get("completeness", 0.0), justification=justifications.get("completeness", "")),
            rigor=DimensionScore(score=scores.get("rigor", 0.0), justification=justifications.get("rigor", "")),
            clarity=DimensionScore(score=scores.get("clarity", 0.0), justification=justifications.get("clarity", "")),
            overall=overall,
        )

class EvaluationStage(PipelineStage):
    """Multi-dimensional proposal evaluation on 5 axes.

    Scores each proposal on Novelty, Feasibility, Completeness, Rigor, Clarity.
    Uses the thinking provider (local LM Studio) for evaluation.

    HB-02: Graceful fallback on LLM failure — stores default scores (all 0.0).
    """

    def __init__(self, provider=None, evaluator=None):
        self._provider = provider
        self._evaluator = evaluator  # Optional: inject for testing

    @property
    def name(self) -> str:
        return "evaluation"

    async def execute(self, ctx: StageContext) -> bool:
        # Check strategy flag
        strategy_config = getattr(ctx, 'params', {}).get('strategy_config', None)
        if strategy_config:
            stage_cfg = strategy_config.stages.get('evaluation')
            if stage_cfg and not stage_cfg.enabled:
                logger.info("Evaluation disabled by strategy — skipping")
                return True

        if not ctx.result.proposals:
            return True

        # Create evaluator if not injected
        evaluator = self._evaluator
        if evaluator is None:
            try:
                from backend.pipeline.evaluation.proposal_evaluator import ProposalEvaluator
                provider = self._provider
                if provider is None:
                    try:
                        from backend.providers.provider_factory import get_thinking_provider
                        from backend.config import get_settings
                        provider = get_thinking_provider(get_settings())
                    except Exception as e:
                        logger.warning("Could not get thinking provider for evaluation: %s", e)
                        provider = None
                evaluator = ProposalEvaluator(provider=provider)
            except Exception as e:
                logger.warning("Failed to create ProposalEvaluator: %s", e)
                return True

        for idx, proposal in ctx.result.proposals.items():
            try:
                proposal_text = ""
                if hasattr(proposal, 'to_markdown'):
                    proposal_text = proposal.to_markdown()
                elif hasattr(proposal, 'sections') and isinstance(proposal.sections, dict):
                    proposal_text = "\n\n".join(f"## {k}\n{v}" for k, v in proposal.sections.items())
                else:
                    proposal_text = str(proposal)

                evaluation = await evaluator.evaluate(proposal_text)

                metadata = self._get_metadata(proposal)
                metadata["evaluation"] = evaluation.to_dict()
                self._set_metadata(proposal, metadata)
                ctx.result.proposals[idx] = proposal

                logger.info(
                    "Evaluated proposal %d: overall=%.2f (N=%.2f F=%.2f C=%.2f R=%.2f Cl=%.2f)",
                    idx, evaluation.overall,
                    evaluation.novelty.score, evaluation.feasibility.score,
                    evaluation.completeness.score, evaluation.rigor.score,
                    evaluation.clarity.score,
                )
            except Exception as e:
                logger.warning("Failed to evaluate proposal %d (non-fatal): %s", idx, e)
                # Store default evaluation (HB-02)
                metadata = self._get_metadata(proposal)
                metadata["evaluation"] = {
                    "novelty": {"score": 0.0, "justification": "Evaluation failed"},
                    "feasibility": {"score": 0.0, "justification": "Evaluation failed"},
                    "completeness": {"score": 0.0, "justification": "Evaluation failed"},
                    "rigor": {"score": 0.0, "justification": "Evaluation failed"},
                    "clarity": {"score": 0.0, "justification": "Evaluation failed"},
                    "overall": 0.0,
                }
                self._set_metadata(proposal, metadata)

        return True

    @staticmethod
    def _get_metadata(proposal) -> dict:
        metadata = {}
        if hasattr(proposal, "metadata") and proposal.metadata:
            if isinstance(proposal.metadata, str):
                try:
                    metadata = json.loads(proposal.metadata)
                except (json.JSONDecodeError, TypeError):
                    metadata = {}
            elif isinstance(proposal.metadata, dict):
                metadata = proposal.metadata
        return metadata

    @staticmethod
    def _set_metadata(proposal, metadata: dict) -> None:
        current = getattr(proposal, "metadata", None)
        if isinstance(current, str) or current is None:
            proposal.metadata = json.dumps(metadata)
        else:
            proposal.metadata = metadata


class GapReflectionStage(PipelineStage):
    """Iterative reflection on gap analysis quality.

    Uses the existing ReflectionStage to evaluate gap quality.
    If score < threshold, regenerates gaps with feedback. Max 2 retries.

    HB-02: Auto-pass on any failure.
    """

    def __init__(self, provider=None, reflector=None, threshold: float = 0.6):
        self._provider = provider
        self._reflector = reflector
        self._threshold = threshold

    @property
    def name(self) -> str:
        return "gap_reflection"

    async def execute(self, ctx: StageContext) -> bool:
        # Check strategy flag
        strategy_config = getattr(ctx, 'params', {}).get('strategy_config', None)
        if strategy_config:
            stage_cfg = strategy_config.stages.get('gap_reflection')
            if stage_cfg and not stage_cfg.enabled:
                logger.info("Gap reflection disabled by strategy — skipping")
                return True

        if not ctx.result.gaps:
            return True

        try:
            reflector = self._reflector
            if reflector is None:
                from backend.pipeline.reflection.reflector import ReflectionStage
                provider = self._provider
                if provider is None:
                    try:
                        from backend.providers.provider_factory import get_thinking_provider
                        from backend.config import get_settings
                        provider = get_thinking_provider(get_settings())
                    except Exception:
                        provider = None
                reflector = ReflectionStage(provider=provider, threshold=self._threshold, max_iterations=3)

            query = getattr(ctx, 'domain', '') or ''
            result = await reflector.reflect_gaps(ctx.result.gaps, query=query)

            logger.info(
                "Gap reflection: score=%.2f passed=%s (iteration %d)",
                result.score, result.passed, result.iteration,
            )

            # Store reflection result in pipeline result metadata
            if not hasattr(ctx.result, 'reflection_results') or ctx.result.reflection_results is None:
                ctx.result.reflection_results = {}
            ctx.result.reflection_results["gap_reflection"] = {
                "score": result.score,
                "passed": result.passed,
                "justification": result.justification,
                "iteration": result.iteration,
            }

        except Exception as e:
            logger.warning("Gap reflection failed (non-fatal, HB-02): %s", e)

        return True


class IdeaReflectionStage(PipelineStage):
    """Iterative reflection on idea generation quality.

    Uses the existing ReflectionStage to evaluate idea quality.
    If score < threshold, regenerates ideas with feedback. Max 2 retries.

    HB-02: Auto-pass on any failure.
    """

    def __init__(self, provider=None, reflector=None, threshold: float = 0.6):
        self._provider = provider
        self._reflector = reflector
        self._threshold = threshold

    @property
    def name(self) -> str:
        return "idea_reflection"

    async def execute(self, ctx: StageContext) -> bool:
        # Check strategy flag
        strategy_config = getattr(ctx, 'params', {}).get('strategy_config', None)
        if strategy_config:
            stage_cfg = strategy_config.stages.get('idea_reflection')
            if stage_cfg and not stage_cfg.enabled:
                logger.info("Idea reflection disabled by strategy — skipping")
                return True

        ideas = getattr(ctx.result, 'ideas', None)
        if not ideas:
            return True

        try:
            reflector = self._reflector
            if reflector is None:
                from backend.pipeline.reflection.reflector import ReflectionStage
                provider = self._provider
                if provider is None:
                    try:
                        from backend.providers.provider_factory import get_thinking_provider
                        from backend.config import get_settings
                        provider = get_thinking_provider(get_settings())
                    except Exception:
                        provider = None
                reflector = ReflectionStage(provider=provider, threshold=self._threshold, max_iterations=3)

            result = await reflector.reflect_ideas(ideas, gaps=ctx.result.gaps)

            logger.info(
                "Idea reflection: score=%.2f passed=%s (iteration %d)",
                result.score, result.passed, result.iteration,
            )

            if not hasattr(ctx.result, 'reflection_results') or ctx.result.reflection_results is None:
                ctx.result.reflection_results = {}
            ctx.result.reflection_results["idea_reflection"] = {
                "score": result.score,
                "passed": result.passed,
                "justification": result.justification,
                "iteration": result.iteration,
            }

        except Exception as e:
            logger.warning("Idea reflection failed (non-fatal, HB-02): %s", e)

        return True

